import sys
MOD = 998244353
it = iter(map(int, sys.stdin.buffer.read().split()))
N = next(it); M = next(it)
# exact[a][r] is the bitset of targets of constraints with these endpoints.
exact = [[0] * (N + 1) for _ in range(N + 2)]
for _ in range(M):
    l = next(it); r = next(it); x = next(it)
    exact[l][r] |= 1 << x
# For each a, prefix[a][b] contains targets of constraints starting at a
# whose right endpoint is at most b.
prefix = [[0] * (N + 1) for _ in range(N + 2)]
for a in range(1, N + 1):
    running = 0
    for b in range(1, N + 1):
        running |= exact[a][b]
        prefix[a][b] = running
bad = [[0] * (N + 1) for _ in range(N + 2)]
for a in range(N, 0, -1):
    for b in range(a, N + 1):
        bad[a][b] = bad[a + 1][b] | prefix[a][b]

C = [[0] * (N + 1) for _ in range(N + 1)]
for n in range(N + 1):
    C[n][0] = C[n][n] = 1
    for k in range(1, n):
        C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % MOD

dp = [[0] * (N + 1) for _ in range(N + 2)]
for i in range(1, N + 2):
    dp[i][i - 1] = 1
for length in range(1, N + 1):
    for a in range(1, N - length + 2):
        b = a + length - 1
        forbidden = bad[a][b]
        total = 0
        for x in range(a, b + 1):
            if not ((forbidden >> x) & 1):
                total += C[length - 1][x - a] * dp[a][x - 1] * dp[x + 1][b]
        dp[a][b] = total % MOD
print(dp[1][N])

