MOD=998244353
import sys
N=int(sys.stdin.readline())
A=list(map(int,sys.stdin.readline().split()))
mx=max(A,default=1)
primes=[]
for p in range(2,mx+1):
    is_prime=True
    for d in range(2,int(p**0.5)+1):
        if p%d==0:
            is_prime=False
            break
    if is_prime:
        primes.append(p)

answer=1
for p in primes:
    steps=[]
    for a in A:
        v=0
        while a%p==0:
            v+=1
            a//=p
        steps.append(v)
    D=sum(steps)
    pw=[1]*(D+1)
    for h in range(1,D+1):
        pw[h]=pw[h-1]*p%MOD

    # hit[h]: paths currently at h that have visited 0;
    # not_hit[h]: paths that have not visited 0.
    hit=[0]*(D+1)
    not_hit=[0]*(D+1)
    hit[0]=1
    for h in range(1,D+1):
        not_hit[h]=pw[h]  # choose starting exponent h

    for a in steps:
        next_hit=[0]*(D+1)
        next_not_hit=[0]*(D+1)
        for h in range(D+1):
            if hit[h]==0 and not_hit[h]==0:
                continue
            destinations=(h,) if a==0 else (h-a,h+a)
            for z in destinations:
                if z<0 or z>D:
                    continue
                factor=pw[z]
                if z==0:
                    next_hit[z]=(next_hit[z]+(hit[h]+not_hit[h])*factor)%MOD
                else:
                    next_hit[z]=(next_hit[z]+hit[h]*factor)%MOD
                    next_not_hit[z]=(next_not_hit[z]+not_hit[h]*factor)%MOD
        hit,not_hit=next_hit,next_not_hit
    answer=answer*sum(hit)%MOD

print(answer)

