def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    it=iter(data); n=next(it); q=next(it)
    parent=list(range(n)); size=[1]*n; left=list(range(n)); right=list(range(n)); color=list(range(1,n+1)); count=[0]+[1]*n
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    def union(a,b):
        a=find(a); b=find(b)
        if a==b:return a
        if size[a]<size[b]: a,b=b,a
        parent[b]=a; size[a]+=size[b]
        left[a]=min(left[a],left[b]); right[a]=max(right[a],right[b])
        return a
    out=[]
    for _ in range(q):
        t=next(it)
        if t==1:
            x=next(it)-1; c=next(it)
            r=find(x); old=color[r]
            if old!=c:
                count[old]-=size[r]; count[c]+=size[r]
                color[r]=c
            for side in (0,1):
                r=find(r)
                nb=left[r]-1 if side==0 else right[r]+1
                if 0<=nb<n:
                    s=find(nb)
                    if color[s]==c:
                        r=union(r,s)
        else:
