from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        largest = second = max_count = 0
        largest_id = -1
        total = 0
        gains = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for left, pair_id in by_right[right]:
                if left > largest:
                    second = largest
                    largest = left
                    max_count = 1
                    largest_id = pair_id
                elif left == largest:
                    max_count += 1
                elif left > second:
                    second = left

            total += right - largest
            if max_count == 1:
                gains[largest_id] += largest - second

        return total + max(gains)

