            by_right[b].append((a,i))
        top1=top2=count=0
        top_id=-1
        base=0
        gain=[0]*len(conflictingPairs)
        for r in range(1,n+1):
            for x,i in by_right[r]:
                if x>top1:
                    top2=top1; top1=x; count=1; top_id=i
                elif x==top1:
                    count+=1
                elif x>top2:
                    top2=x
            base += r-top1
            if count==1:
                gain[top_id] += top1-top2
        return base+max(gain)

