import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = []
    for _ in range(m):
        edges.append((next(it)-1, next(it)-1, next(it)))

    queries = []
    closed = set()
    for _ in range(q):
        t = next(it)
        if t == 1:
            idx = next(it)-1
            queries.append((1, idx))
            closed.add(idx)
        else:
            queries.append((2, next(it)-1, next(it)-1))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for idx, (a, b, c) in enumerate(edges):
        if idx not in closed:
            dist[a][b] = dist[b][a] = c

    # APSP for the graph after all forward deletions.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            row_i = dist[i]
            dik = row_i[k]
            if dik == inf:
                continue
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            value = dist[x][y]
            answers.append(str(value if value < inf else -1))
        else:
            _, idx = query
            a, b, c = edges[idx]
            # Adding one undirected edge: every new shortest path uses it at
            # most once, so it is the minimum of the old path and paths through it.
            row_a = dist[a][:]
            row_b = dist[b][:]
            col_a = [dist[i][a] for i in range(n)]
            col_b = [dist[i][b] for i in range(n)]
            for i in range(n):
                row_i = dist[i]
                to_a, to_b = col_a[i], col_b[i]
                for j in range(n):
                    via_ab = to_a + c + row_b[j]
                    if via_ab < row_i[j]:
                        row_i[j] = via_ab
                    via_ba = to_b + c + row_a[j]
                    if via_ba < row_i[j]:
                        row_i[j] = via_ba

    sys.stdout.write('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

