import sys

def main():
    input=sys.stdin.readline
    n=int(input())
    a=[0]+list(map(int,input().split()))
    pref=[0]*(n+1)
    seen=set()
    for i in range(1,n+1):
        if a[i] not in seen:
            seen.add(a[i])
        pref[i]=len(seen)
    suf=[0]*(n+2)
    seen=set()
    for i in range(n,0,-1):
        seen.add(a[i]); suf[i]=len(seen)
    size=1
    while size<n: size*=2
    neg=-10**9
    mx=[neg]*(2*size)
    lazy=[0]*(2*size)
    def apply(node,v):
        mx[node]+=v; lazy[node]+=v
    def push(node):
        if lazy[node]:
            apply(node*2,lazy[node]); apply(node*2+1,lazy[node]); lazy[node]=0
    def point(node,l,r,pos,val):
        if l==r:
            mx[node]=val; lazy[node]=0; return
        push(node); m=(l+r)//2
        if pos<=m: point(node*2,l,m,pos,val)
        else: point(node*2+1,m+1,r,pos,val)
        mx[node]=max(mx[node*2],mx[node*2+1])
    def add(node,l,r,ql,qr,v):
        if ql<=l and r<=qr: apply(node,v); return
        push(node); m=(l+r)//2
        if ql<=m: add(node*2,l,m,ql,qr,v)
        if qr>m: add(node*2+1,m+1,r,ql,qr,v)
        mx[node]=max(mx[node*2],mx[node*2+1])
    last=[0]*(n+1)
    ans=0
    for j in range(2,n):
        i=j-1
        point(1,1,size,i,pref[i])
        p=last[a[j]]
        left=max(1,p)
        if left<=j-1: add(1,1,size,left,j-1,1)
        last[a[j]]=j
        ans=max(ans,mx[1]+suf[j+1])
    print(ans)
