class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        s = [0] * (n + 1)
        s[0] = 1
        for i in range(1, n + 1):
            for k in range(i, 0, -1):
                s[k] = (s[k - 1] + k * s[k]) % MOD
            s[0] = 0
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        ans = 0
        choose = 1
        for k in range(1, min(n, x) + 1):
            if k > 1:
                choose = choose * (x - k + 1) % MOD * pow(k, MOD - 2, MOD) % MOD
            ans = (ans + choose * fact[k] % MOD * s[k] % MOD * pow(y, k, MOD)) % MOD
        return ans

