from math import comb
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD=10**9+7
        n=len(s)
        # steps[i] is the number of popcount operations needed to reach 1.
        steps=[0]*(n+1)
        for i in range(2,n+1):
            steps[i]=1+steps[i.bit_count()]
        eligible=[i for i in range(1,n+1) if steps[i]<k]
        # Count values below s by their number of set bits.
        ways=[0]*(n+1)
        ones=0
        for pos,ch in enumerate(s):
            if ch=='1':
                rem=n-pos-1
                for w in range(ones,n+1):
                    need=w-ones
                    if need<=rem:
                        ways[w]=(ways[w]+comb(rem,need))%MOD
                ones+=1
        return sum(ways[w] for w in eligible)%MOD

