import sys, heapq

N = int(sys.stdin.readline())
g = [sys.stdin.readline().strip() for _ in range(N)]
incoming = [[[] for _ in range(26)] for _ in range(N)]
outgoing = [[[] for _ in range(26)] for _ in range(N)]
for u in range(N):
    for v, ch in enumerate(g[u]):
        if ch != '-':
            c = ord(ch) - 97
            outgoing[u][c].append(v)
            incoming[v][c].append(u)

# In a complete labeled graph, every answer is already 0 or 1.
if all(ch != '-' for row in g for ch in row):
    print('\n'.join(' '.join('0' if i == j else '1' for j in range(N)) for i in range(N)))
    raise SystemExit

INF = 10**9
dist = [[INF] * N for _ in range(N)]
heap = []
for i in range(N):
    dist[i][i] = 0
    heapq.heappush(heap, (0, i, i))
for u in range(N):
    for v, ch in enumerate(g[u]):
        if ch != '-' and dist[u][v] > 1:
            dist[u][v] = 1
            heapq.heappush(heap, (1, u, v))

while heap:
    d, u, v = heapq.heappop(heap)
    if dist[u][v] != d:
        continue
    nd = d + 2
    for c in range(26):
        left = incoming[u][c]
        right = outgoing[v][c]
        if not left or not right:
            continue
        for x in left:
            row = dist[x]
            for y in right:
                if nd < row[y]:
                    row[y] = nd
                    heapq.heappush(heap, (nd, x, y))

print('\n'.join(' '.join(str(-1 if x == INF else x) for x in row) for row in dist))

