    if not data:
        return
    n, x = data[0], data[1]
    u = data[2::2]
    d = data[3::2]

    # Feasible H values are monotone: if H works, every smaller H works.
    high = min(a + b for a, b in zip(u, d))

    def feasible(h):
        lo = max(0, h - d[0])
        hi = u[0]
        if lo > hi:
            return False
        for i in range(1, n):
            # Reachable upper-tooth lengths after enforcing the adjacent bound.
            lo = max(0, h - d[i], lo - x)
            hi = min(u[i], hi + x)
            if lo > hi:
                return False
        return True

    left = 0
    while left < high:
        mid = (left + high + 1) // 2
        if feasible(mid):
            left = mid
        else:
            high = mid - 1

    print(sum(a + b for a, b in zip(u, d)) - n * left)

if __name__ == '__main__':
    main()

