import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    # For each A, the crease at index i+A is a mountain precisely when
    # v2(i+A) is even. Its 100-bit residue target is -A modulo 2^100.
    limit = 1 << 100
    targets = [(limit - x) % limit for x in a]

    # A trie of target bits, examined from least significant to most
    # significant. If i first differs from -A at bit k, then v2(i+A)=k.
    children = [[-1, -1]]
    counts = [0]
    for t in targets:
        node = 0
        counts[node] += 1
        for k in range(100):
            bit = (t >> k) & 1
            nxt = children[node][bit]
            if nxt == -1:
                nxt = len(children)
                children[node][bit] = nxt
                children.append([-1, -1])
                counts.append(0)
            node = nxt
            counts[node] += 1

    # Bottom-up: choose each bit of i to maximize the mountain count.
    # At depth 100, a still-matching target has valuation at least 100;
    # the represented crease indices are below 2^100, so its valuation
    # is exactly 100.
    best = [0] * len(children)
    depth = [0] * len(children)
    stack = [(0, 0, False)]
    while stack:
        node, d, visited = stack.pop()
        if not visited:
            stack.append((node, d, True))
            if d < 100:
                for child in children[node]:
                    if child != -1:
                        stack.append((child, d + 1, False))
        else:
            if d == 100:
                best[node] = counts[node] if d % 2 == 0 else 0
            else:
                score = 1 if d % 2 == 0 else 0
                options = []
                for child in children[node]:
                    if child != -1:
                        options.append(best[child])
                best[node] = max((v + score * 0 for v in options), default=0)
                # Targets that branch away at this bit have valuation d.
                for bit in range(2):
                    child = children[node][bit]
                    if child != -1:
                        other = children[node][1 - bit]
                        # The chosen bit is 1-bit; all targets in the
                        # opposite branch mismatch here.
                        if other != -1:
                            best[node] = max(best[node], best[child] + (counts[other] if d % 2 == 0 else 0))

    print(best[0])

