from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order: NE, SE, SW, NW.
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]
        straight = [[[0] * m for _ in range(n)] for _ in range(4)]
        turned = [[[0] * m for _ in range(n)] for _ in range(4)]

        def traversal(d):
            dr, dc = dirs[d]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            return rows, cols

        # Longest valid straight sequence beginning at each cell (which is 0 or 2).
        for d, (dr, dc) in enumerate(dirs):
            rows, cols = traversal(d)
            for r in rows:
                for c in cols:
                    value = grid[r][c]
                    if value == 1:
                        continue
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < n and 0 <= nc < m and
                            grid[nr][nc] == 2 - value):
                        straight[d][r][c] = 1 + straight[d][nr][nc]
                    else:
                        straight[d][r][c] = 1

        # turned[d][r][c]: best continuation from this cell moving in direction d,
        # with at most one clockwise turn still available.
        for d in range(4):
            rows, cols = traversal(d)
            for r in rows:
                for c in cols:
                    value = grid[r][c]
                    if value == 1:
                        continue
                    expected = 2 - value
                    length = 1
                    for nd in (d, (d + 1) % 4):
                        dr, dc = dirs[nd]
                        nr, nc = r + dr, c + dc
                        if (0 <= nr < n and 0 <= nc < m and
                                grid[nr][nc] == expected):
                            tail = turned[d][nr][nc] if nd == d else straight[nd][nr][nc]
                            length = max(length, 1 + tail)
                    turned[d][r][c] = length

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2):
                        answer = max(answer, 1 + turned[d][nr][nc])
        return answer

