class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # 10^i modulo k, where i is the position counted from the right.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        # Each chosen left-half digit contributes at its own position and,
        # except for the middle digit, at its mirrored position as well.
        coeff = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        # dp[i][r]: can positions i..m-1 contribute residue r modulo k?
        dp = [bytearray(k) for _ in range(m + 1)]
        dp[m][0] = 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            low = 1 if i == 0 else 0
            row = dp[i]
            nxt = dp[i + 1]
            for residue in range(k):
                for digit in range(low, 10):
                    if nxt[(residue - c * digit) % k]:
                        row[residue] = 1
                        break

        # Greedily choose the largest digit that leaves a feasible suffix.
        chosen = []
        residue = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for digit in range(9, low - 1, -1):
                new_residue = (residue + c * digit) % k
                if dp[i + 1][(-new_residue) % k]:
                    chosen.append(str(digit))
                    residue = new_residue
                    break

        left = ''.join(chosen)
        if n % 2:
            return left + left[:-1][::-1]
        return left + left[::-1]

