from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # The prefix maximum starting at i remains nums[i] up to (but not
        # including) the next index whose value is strictly greater.
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        log = n.bit_length()
        jump = [[n] * n for _ in range(log)]
        area = [[0] * n for _ in range(log)]
        for i in range(n):
            jump[0][i] = nxt[i]
            area[0][i] = (nxt[i] - i) * nums[i]

        # Binary lifting along successive prefix-maximum plateaus.
        for b in range(1, log):
            prev_jump, prev_area = jump[b - 1], area[b - 1]
            this_jump, this_area = jump[b], area[b]
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    this_jump[i] = prev_jump[mid]
                    this_area[i] = prev_area[i] + prev_area[mid]
                else:
                    this_area[i] = prev_area[i]

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def cost(left: int, right: int) -> int:
            # Sum of prefix maxima minus sum of the original values.
            cur = left
            raised_sum = 0
            for b in range(log - 1, -1, -1):
                following = jump[b][cur]
                if following <= right:
                    raised_sum += area[b][cur]
                    cur = following
            raised_sum += (right - cur + 1) * nums[cur]
            return raised_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for right in range(n):
            lo, hi = 0, right + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

