import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, len(data), 2)]

    # In an optimal ordering, lower (A-1)/B functions are applied first.
    def compare(x, y):
        lhs = (x[0] - 1) * y[1]
        rhs = (y[0] - 1) * x[1]
        return (lhs > rhs) - (lhs < rhs)

    funcs.sort(key=cmp_to_key(compare))
    dp = [None] * (k + 1)
    dp[0] = 1
    for i, (a, b) in enumerate(funcs, 1):
        for count in range(min(k, i), 0, -1):
            prev = dp[count - 1]
            if prev is not None:
                value = a * prev + b
                if dp[count] is None or value > dp[count]:
                    dp[count] = value
    print(dp[k])

if __name__ == '__main__':
    main()

