class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        score = [array('I', [0]) * n for _ in range(n)]
        best = [array('I', [0]) * n for _ in range(n)]

        for i, x in enumerate(nums):
            score[i][i] = x
            best[i][i] = x

        # Increasing interval length; for each row, its left dependency is
        # already computed, and the next row was completed in the prior pass.
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
                s = score[i][j - 1] ^ score[i + 1][j]
                score[i][j] = s
                b = best[i][j - 1]
                if best[i + 1][j] > b:
                    b = best[i + 1][j]
                if s > b:
                    b = s
                best[i][j] = b

        return [best[l][r] for l, r in queries]

