class Solution:
    def makeStringGood(self, s: str) -> int:
        freq = [0] * 26
        for ch in s:
            freq[ord(ch) - 97] += 1
        ans = len(s)
        # For a fixed positive common frequency, scan left to right. Surplus
        # characters can be advanced to the next letter to fill its deficit.
        for target in range(1, len(s) + 1):
            cost = 0
            carry = 0
            for i in range(26):
                count = freq[i] + carry
                carry = 0
                if count == 0:
                    cost += target
                elif count < target:
                    cost += target - count
                else:
                    extra = count - target
                    cost += extra
                    carry = extra
            # Characters advanced beyond z cannot be retained.
            cost += carry
            ans = min(ans, cost)
        return ans

