import sys

def main():
    data=sys.stdin.buffer.read().split()
    K=int(data[0]); S=data[1]; T=data[2]
    n=len(S); m=len(T)
    if abs(n-m)>K:
        print('No'); return
    def snake(i,k):
        j=i-k
        while i<n and j<m and S[i]==T[j]:
            i+=1; j+=1
        return i
    prev={0:snake(0,0)}
    if prev.get(n-m,-1)==n:
        print('Yes'); return
    for d in range(1,K+1):
        cur={}
        for k in range(-d,d+1):
            best=-1
            # Each edit transition, retaining only valid resulting coordinates.
            if k in prev:
                i=prev[k]+1; j=i-k
                if i<=n and 0<=j<=m: best=max(best,i)  # substitution
            if k-1 in prev:
                i=prev[k-1]+1; j=i-k
                if i<=n and 0<=j<=m: best=max(best,i)  # deletion
            if k+1 in prev:
                i=prev[k+1]; j=i-k
                if 0<=i<=n and 0<=j<=m: best=max(best,i)  # insertion
            if best<0: continue
            i=snake(best,k)
            cur[k]=i
            if i==n and i-k==m:
                print('Yes'); return
        prev=cur
    print('No')
main()

