from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Iterative postorder, visiting children in increasing node order.
        order = []
        stack = [(0, False)]
        while stack:
            v, exiting = stack.pop()
            if exiting:
                order.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        # Every subtree occupies a contiguous segment of the postorder.
        subtree_size = [1] * n
        position = [0] * n
        for i, v in enumerate(order):
            position[v] = i
            p = parent[v]
            if p != -1:
                subtree_size[p] += subtree_size[v]

        text = ''.join(s[v] for v in order)

        # Manacher radii: odd[i] includes the center; even[i] is centered
        # between i-1 and i.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
