class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        # Best totals ending with each drink at the current hour and one before.
        a_prev, b_prev = energyDrinkA[0], energyDrinkB[0]
        a_two = b_two = 0

        for i in range(1, n):
            if i == 1:
                a_cur = a_prev + energyDrinkA[i]
                b_cur = b_prev + energyDrinkB[i]
            else:
                # Switching requires the preceding hour to be spent cleansing.
                a_cur = energyDrinkA[i] + max(a_prev, b_two)
                b_cur = energyDrinkB[i] + max(b_prev, a_two)

            a_two, b_two = a_prev, b_prev
            a_prev, b_prev = a_cur, b_cur

        return max(a_prev, b_prev)

