from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Minimum prefix sum seen at each prefix-index residue modulo k.
        min_prefix = [None] * k
        min_prefix[0] = 0

        prefix_sum = 0
        best = None
        for i, value in enumerate(nums, 1):
            prefix_sum += value
            residue = i % k

            # Same residue means the subarray length is divisible by k.
            previous = min_prefix[residue]
            if previous is not None:
                candidate = prefix_sum - previous
                if best is None or candidate > best:
                    best = candidate

            if previous is None or prefix_sum < previous:
                min_prefix[residue] = prefix_sum

        return best

