class Solution:
    def countPairs(self, nums: List[int]) -> int:
        width = max(len(str(x)) for x in nums)
        seen = {}
        answer = 0

        for x in nums:
            s = str(x).zfill(width)
            candidates = {s}
            chars = list(s)
            for i in range(width):
                for j in range(i + 1, width):
                    if chars[i] != chars[j]:
                        chars[i], chars[j] = chars[j], chars[i]
                        candidates.add(''.join(chars))
                        chars[i], chars[j] = chars[j], chars[i]
            answer += sum(seen.get(candidate, 0) for candidate in candidates)
            seen[s] = seen.get(s, 0) + 1

        return answer

