class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # A jump from i to j contributes nums[i] * (j - i), so
        # each reachable i defines the line nums[i] * j + dp[i] - i*nums[i].
        tree = [None] * (4 * n)

        def add(line, node, left, right):
            current = tree[node]
            if current is None:
                tree[node] = line
                return

            mid = (left + right) // 2
            if line[0] * mid + line[1] > current[0] * mid + current[1]:
                tree[node], line = line, current
                current = tree[node]

            if left == right:
                return
            if line[0] * left + line[1] > current[0] * left + current[1]:
                add(line, node * 2, left, mid)
            elif line[0] * right + line[1] > current[0] * right + current[1]:
                add(line, node * 2 + 1, mid + 1, right)

        def query(x):
            node, left, right = 1, 0, n - 1
            best = None
            while True:
                line = tree[node]
                if line is not None:
                    value = line[0] * x + line[1]
                    if best is None or value > best:
                        best = value
                if left == right:
                    return best
                mid = (left + right) // 2
                if x <= mid:
                    node, right = node * 2, mid
                else:
                    node, left = node * 2 + 1, mid + 1

        add((nums[0], 0), 1, 0, n - 1)
        answer = 0
        for j in range(1, n):
            answer = query(j)
            add((nums[j], answer - j * nums[j]), 1, 0, n - 1)
        return answer

