class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = {}
        for value in nums:
            freq[value] = freq.get(value, 0) + 1

        largest = None
        for outlier in nums:
            remainder = total - outlier
            if remainder % 2 != 0:
                continue

            sum_value = remainder // 2
            available = freq.get(sum_value, 0)
            if sum_value == outlier:
                available -= 1  # The outlier itself cannot be the sum element.

            if available > 0 and (largest is None or outlier > largest):
                largest = outlier

        return largest

