import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        # The cost includes the starting value and every value reached.
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            digits = str(x)
            for i, ch in enumerate(digits):
                digit = int(ch)
                place = 10 ** (len(digits) - 1 - i)
                for new_digit in (digit - 1, digit + 1):
                    if 0 <= new_digit <= 9:
                        y = x + (new_digit - digit) * place
                        if is_prime[y]:
                            continue
                        new_cost = cost + y
                        if new_cost < dist.get(y, float('inf')):
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))
        return -1

