class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z0[i] is the common-prefix length of nums and nums[i:]
        z0 = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z0[i] = min(right - i, z0[i - left])
            while i + z0[i] < n and nums[z0[i]] == nums[i + z0[i]]:
                z0[i] += 1
            if i + z0[i] > right:
                left, right = i, i + z0[i]

        answer = 0
        # i: end of nums1; d: length of nums2
        for i in range(1, n - 1):
            m = n - i

            # z[k] compares nums[i:] with nums[i+k:]
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k < right:
                    z[k] = min(right - k, z[k - left])
                while k + z[k] < m and nums[i + z[k]] == nums[i + k + z[k]]:
                    z[k] += 1
                if k + z[k] > right:
                    left, right = k, k + z[k]

            for d in range(1, m):
                j = i + d
                # nums1 is a prefix of nums2
                first_condition = d >= i and z0[i] >= i
                # nums2 is a prefix of nums3
                second_condition = d <= n - j and z[d] >= d
                if first_condition or second_condition:
                    answer += 1

        return answer

