from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        target = set(targetIndices)
        neg = -10**9
        # dp[j]: max removals among processed positions while retaining
        # a subsequence matching the first j characters of pattern.
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            ndp = dp[:]  # keep this character, without using it for pattern

            if i in target:
                for j, value in enumerate(dp):
                    if value != neg:
                        ndp[j] = max(ndp[j], value + 1)

            # Keep and use this character to match the next pattern character.
            for j in range(m):
                if ch == pattern[j] and dp[j] != neg:
                    ndp[j + 1] = max(ndp[j + 1], dp[j])

            dp = ndp

        return dp[m]

