import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse the edges and find each node's minimum bottleneck path to 0.
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        inf = 10**18
        dist = [inf] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            cost, v = heapq.heappop(heap)
            if cost != dist[v]:
                continue
            for u, weight in rev[v]:
                candidate = max(cost, weight)
                if candidate < dist[u]:
                    dist[u] = candidate
                    heapq.heappush(heap, (candidate, u))

        answer = max(dist)
        return -1 if answer == inf else answer

