class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Run-length encode the augmented string. Its end runs of 1s ensure
        # every zero run is bounded by 1s.
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        one_runs = [i for i, (c, _) in enumerate(runs) if c == '1' and 0 < i < len(runs) - 1]
        zero_runs = [i for i, (c, _) in enumerate(runs) if c == '0']
        best_gain = 0  # choosing no trade is allowed

        # Flipping an internal 1-run merges its two neighboring zero runs;
        # converting that merged run gains the sum of those zero lengths.
        for i in one_runs:
            best_gain = max(best_gain, runs[i - 1][1] + runs[i + 1][1])

        # The second block need not be the newly merged block: it may be a
        # different zero run. In that case the net gain is zero_run - flipped_1_run.
        # Find the best such pair, excluding the two zero runs adjacent to it.
        if len(zero_runs) >= 3:
            top = sorted(zero_runs, key=lambda k: runs[k][1], reverse=True)[:3]
            for i in one_runs:
                for z in top:
                    if z != i - 1 and z != i + 1:
                        best_gain = max(best_gain, runs[z][1] - runs[i][1])

        return s.count('1') + best_gain

